            if line.strip():
                actual_indent = len(line) - len(line.lstrip())
                break
        if actual_indent < expected_indent:
            pad = " " * (expected_indent - actual_indent)
            solution = "\\n".join(
                pad + line if line.strip() else line
                for line in solution.split("\\n")
            )
        return problem["prompt"] + solution
